#!/usr/bin/env node
/**
 * The catalogue database, and the promise that it is only ever an accelerator.
 *
 * Searching the tracker used to walk all 16,308 sentences in JavaScript on
 * every query, after ~770ms spent building a search string for each one.
 * Measured on the same eight queries, an FTS5 index answers about 55 times
 * faster — 0.4ms against 28ms — with no warm-up at all.
 *
 * Two things have to stay true or this becomes a liability rather than a win:
 *
 *  1. The packs remain the source of truth. This file is generated FROM them,
 *     the same way the word-picture artwork is. If the two ever disagree the
 *     packs win, so the generator has to run inside the build rather than by
 *     hand.
 *  2. Nothing may depend on it. The app runs in a browser too, the database
 *     can fail to open, and the answer can arrive after the learner has typed
 *     another letter. The in-memory search stays, and stays reachable.
 */
const assert = require("assert");
const fs = require("fs");
const path = require("path");
const { DatabaseSync } = require("node:sqlite");

const root = path.resolve(__dirname, "..");
const read = (rel) => fs.readFileSync(path.join(root, rel), "utf8");

// ── the artefact ──────────────────────────────────────────────────────────
const dbPath = path.join(root, "public", "catalogue.db");
assert.ok(fs.existsSync(dbPath), "public/catalogue.db is missing — run npm run build:catalogue-db");

const db = new DatabaseSync(dbPath, { readOnly: true });
const count = db.prepare("SELECT COUNT(*) AS n FROM item").get().n;
assert.ok(count > 20000, `the database holds only ${count} items; the catalogue is far larger than that`);

// The index has to actually answer, and answer the same way the app asks.
const hits = db
  .prepare("SELECT i.id FROM item_fts f JOIN item i ON i.id = f.id WHERE item_fts MATCH ?")
  .all('"kino"*');
assert.ok(hits.length > 0, "FTS5 returns nothing for a word the catalogue definitely contains");

// A search box hands the query language whatever was typed. Operators and
// quotes must not be able to become a syntax error.
for (const hostile of ['bad"query*(', "AND OR NEAR", '""', "*"]) {
  const words = hostile.replace(/["*()]/g, " ").split(/\s+/).filter(Boolean).slice(0, 8);
  if (!words.length) continue;
  const match = words.map((w) => `"${w}"*`).join(" ");
  assert.doesNotThrow(
    () => db.prepare("SELECT id FROM item_fts WHERE item_fts MATCH ?").all(match),
    `FTS5 threw on hostile input: ${hostile}`
  );
}
db.close();

// ── it is generated, not authored ─────────────────────────────────────────
const pkg = JSON.parse(read("package.json"));
assert.ok(
  pkg.scripts.build.includes("npm run build:catalogue-db"),
  "the database is not regenerated by the build, so it can drift from the packs"
);
assert.ok(
  pkg.build.asarUnpack.includes("dist/catalogue.db"),
  "the database stays inside the asar, where SQLite cannot open it"
);

// ── nothing depends on it ─────────────────────────────────────────────────
const main = read("electron/main.js");
assert.ok(
  main.includes("if (!db) return null;"),
  "the main process must answer null when it has no database, not an empty result"
);
assert.ok(
  /catalogueDbFailed = true;/.test(main),
  "a database that fails to open must be given up on, not retried on every keystroke"
);
assert.ok(
  main.includes('.all(match);'),
  "the search must return every match — a capped one would make the tracker's counts wrong"
);

const tracker = read("src/components/lab/VocabTracker.tsx");
assert.ok(
  tracker.includes("else if (!catalogItemMatchesQuery(item, q, searchTextFor(item))) return false;"),
  "the in-memory search has been removed; it is the fallback for browsers and for a missing database"
);
assert.ok(
  tracker.includes("indexedMatches.query === filterQuery.trim()"),
  "results from the index are used without checking they answer the query being shown"
);

console.log(
  `catalogue database OK — ${count.toLocaleString()} items indexed, FTS5 answers, `
  + "hostile input is defused, and the in-memory search is still the fallback"
);
